import{_ as t,o as a,c as n,a2 as s}from"./chunks/framework.BS0bAV7E.js";const u=JSON.parse('{"title":"中文控制台层","description":"","frontmatter":{},"headers":[],"relativePath":"zh/manual/chinese-console.md","filePath":"zh/manual/chinese-console.md"}'),c={name:"zh/manual/chinese-console.md"};function o(d,e,i,l,r,p){return a(),n("div",null,[...e[0]||(e[0]=[s(`<h1 id="中文控制台层" tabindex="-1">中文控制台层 <a class="header-anchor" href="#中文控制台层" aria-label="Permalink to &quot;中文控制台层&quot;">​</a></h1><p>Open Cube OS 保持所有系统可见字符串为 ASCII，同时通过 <code>chinese/</code> 下的专用层渲染中文用户内容。</p><h2 id="是什么" tabindex="-1">是什么 <a class="header-anchor" href="#是什么" aria-label="Permalink to &quot;是什么&quot;">​</a></h2><table tabindex="0"><thead><tr><th>组件</th><th>文件</th><th>功能</th></tr></thead><tbody><tr><td>16x16 CJK 字体</td><td><code>chinese/chinese_font_data.c</code></td><td>控制台的位图字形</td></tr><tr><td>GB 编码</td><td><code>chinese/encoding.c</code></td><td>gb2312 / utf-8 / ascii 编解码器</td></tr><tr><td>中文控制台</td><td><code>chinese/console_cn.c</code></td><td>在帧缓冲上渲染 CJK 行</td></tr><tr><td>渲染器</td><td><code>chinese/render_cn.c</code></td><td>字形光栅管道</td></tr><tr><td>拼音输入法</td><td><code>chinese/pinyin_data.c</code> + ime</td><td>音节解析与输入</td></tr><tr><td>中文 TUI 应用</td><td><code>tui_cn_*.c</code></td><td>中文界面的硬件/网络/系统信息</td></tr></tbody></table><h2 id="命令" tabindex="-1">命令 <a class="header-anchor" href="#命令" aria-label="Permalink to &quot;命令&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>oc&gt; chinese          (status: font / encoding / render / ime)</span></span>
<span class="line"><span>oc&gt; chinesetest      (full Chinese-support regression suite)</span></span>
<span class="line"><span>oc&gt; font             (list registered fonts + active renderer)</span></span>
<span class="line"><span>oc&gt; font-test        (render a mixed CJK/ASCII sample row)</span></span>
<span class="line"><span>oc&gt; encoding         (codec status: gb2312 / utf-8 / ascii)</span></span>
<span class="line"><span>oc&gt; encoding-test    (quick codec round-trip check)</span></span>
<span class="line"><span>oc&gt; ime              (pinyin IME status)</span></span>
<span class="line"><span>oc&gt; ime -i           (interactive pinyin input on the console line)</span></span>
<span class="line"><span>oc&gt; lang             (language console switch)</span></span></code></pre></div><h2 id="设计规则" tabindex="-1">设计规则 <a class="header-anchor" href="#设计规则" aria-label="Permalink to &quot;设计规则&quot;">​</a></h2><ul><li><strong>系统字符串为 ASCII</strong>：命令名、提示符、启动消息、帮助文本——这是固件/硬件兼容性契约（参见 <code>CONTRIBUTING.md</code> 基本规则 1）。</li><li><strong>用户内容可为任意</strong>：文件名、文件内容、编辑器缓冲区、网络负载——中文层在控制台和 TUI 中渲染它们。</li></ul><p>因此，没有 CJK 字体的终端仍能获得完全可用的系统；启用该层后，混合语言内容能正确显示。</p><h2 id="构建配置" tabindex="-1">构建配置 <a class="header-anchor" href="#构建配置" aria-label="Permalink to &quot;构建配置&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>make CONFIG_CHINESE=n     (also forces CONFIG_TUI=n)</span></span></code></pre></div><p>关闭路径是真实代码：<code>console_cn</code> 路由到 <code>screen_console</code> 中的 ASCII 等价物，配置器生成的头文件将禁用的调用映射到这些等价物。<code>CONFIG_CHINESE=n CONFIG_TUI=n</code> 构建启动时有 216 条命令（233 - 17 条中文/TUI 命令）——完整配置启动时有 233 条。</p>`,12)])])}const g=t(c,[["render",o]]);export{u as __pageData,g as default};
